fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        let lines: Vec<String> = if keepends {
            // Split keeping line endings
            s.lines()
                .map(|line| {
                    // Find the original line with its ending
                    let mut line_with_ending = String::new();
                    for ch in line.chars() {
                        line_with_ending.push(ch);
                    }
                    // Add the line ending if it exists in the original
                    if let Some(next_char) = s.chars().nth(line_with_ending.len()) {
                        if next_char == '\r' || next_char == '\n' {
                            line_with_ending.push(next_char);
                            // Check for \r\n sequence
                            if next_char == '\r' {
                                if let Some(next_next_char) = s.chars().nth(line_with_ending.len()) {
                                    if next_next_char == '\n' {
                                        line_with_ending.push(next_next_char);
                                    }
                                }
                            }
                        }
                    }
                    line_with_ending
                })
                .collect()
        } else {
            // Split without keeping line endings (simple case)
            s.lines().map(|line| line.to_string()).collect()
        };
        
        // Ensure the inner vector is non-empty
        // If the string is empty or contains no lines, we still need at least one element
        if lines.is_empty() {
            result.push(vec![String::new()]);
        } else {
            result.push(lines);
        }
    }
    
    result
}